"use client"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { useAuth } from "@/lib/auth-context"
import { TrendingUp, Clock, CheckCircle2, AlertTriangle, Users, Loader2 } from "lucide-react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import { useEffect, useState } from "react"

interface DashboardStats {
  totalSignalements: number
  nouveauxSignalements: number
  enAttente: number
  enCours: number
  resolus: number
  resolusCeMois: number
  recentSignalements: Array<{
    id: number
    titre: string
    statut: string
    priorite: string
    dateCreation: string
  }>
  techniciensStats: Array<{
    id: number
    nom: string
    prenom: string
    actifs: number
    resolus: number
  }>
}

export default function AdminDashboard() {
  const { user, isAuthenticated } = useAuth()
  const router = useRouter()
  const [stats, setStats] = useState<DashboardStats | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (!isAuthenticated) {
      router.push("/login")
      return
    } else if (user?.role !== "ADMIN") {
      router.push("/")
      return
    }

    const fetchStats = async () => {
      try {
        setIsLoading(true)
        setError(null)

        const token = localStorage.getItem("token")
        if (!token) {
          throw new Error("Token d'authentification manquant")
        }

        const apiUrl = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8080"
        const response = await fetch(`${apiUrl}/api/admin/dashboard/stats`, {
          method: "GET",
          headers: {
            "Authorization": `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        })

        if (!response.ok) {
          if (response.status === 401 || response.status === 403) {
            localStorage.removeItem("token")
            localStorage.removeItem("user")
            router.push("/login")
            return
          }
          throw new Error(`Erreur ${response.status}: ${response.statusText}`)
        }

        const data = await response.json()
        setStats(data)
      } catch (err: any) {
        console.error("Erreur lors de la récupération des statistiques:", err)
        setError(err.message || "Une erreur est survenue lors du chargement des statistiques")
      } finally {
        setIsLoading(false)
      }
    }

    fetchStats()
  }, [isAuthenticated, user, router])

  if (!isAuthenticated || user?.role !== "ADMIN") {
    return null
  }

  const formatDate = (dateString: string) => {
    if (!dateString) return "Date inconnue"
    try {
      const date = new Date(dateString)
      const now = new Date()
      const diffMs = now.getTime() - date.getTime()
      const diffMins = Math.floor(diffMs / 60000)
      const diffHours = Math.floor(diffMs / 3600000)
      const diffDays = Math.floor(diffMs / 86400000)

      if (diffMins < 1) return "À l'instant"
      if (diffMins < 60) return `Il y a ${diffMins} min`
      if (diffHours < 24) return `Il y a ${diffHours}h`
      if (diffDays < 7) return `Il y a ${diffDays}j`
      return date.toLocaleDateString("fr-FR")
    } catch {
      return dateString
    }
  }

  const statsCards = stats ? [
    {
      title: "Total signalements",
      value: stats.totalSignalements.toLocaleString("fr-FR"),
      icon: AlertTriangle,
    },
    {
      title: "En attente",
      value: stats.enAttente.toLocaleString("fr-FR"),
      icon: Clock,
    },
    {
      title: "En cours",
      value: stats.enCours.toLocaleString("fr-FR"),
      icon: TrendingUp,
    },
    {
      title: "Résolus ce mois",
      value: stats.resolusCeMois.toLocaleString("fr-FR"),
      icon: CheckCircle2,
    },
  ] : []

  return (
    <div className="min-h-screen bg-background">
      {/* Main Content */}
      <main className="container mx-auto px-4 py-8">
        <div className="mb-8">
          <h1 className="mb-2 text-3xl font-bold">Tableau de bord administrateur</h1>
          <p className="text-muted-foreground">Vue d'ensemble de l'activité et des signalements</p>
        </div>

        {/* Stats Grid */}
        <div className="mb-8 grid gap-6 md:grid-cols-2 lg:grid-cols-4">
          {stats.map((stat) => {
            const Icon = stat.icon
            return (
              <Card key={stat.title}>
                <CardHeader className="flex flex-row items-center justify-between pb-2">
                  <CardTitle className="text-sm font-medium text-muted-foreground">{stat.title}</CardTitle>
                  <Icon className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold">{stat.value}</div>
                  <p className={`text-xs ${stat.trend === "up" ? "text-accent" : "text-destructive"}`}>
                    {stat.change} par rapport au mois dernier
                  </p>
                </CardContent>
              </Card>
            )
          })}
        </div>

        <div className="grid gap-8 lg:grid-cols-3">
          {/* Recent Signalements */}
          <Card className="lg:col-span-2">
            <CardHeader>
              <CardTitle>Signalements récents</CardTitle>
              <CardDescription>Dernières activités sur la plateforme</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {recentSignalements.map((signalement) => (
                  <div
                    key={signalement.id}
                    className="flex items-center justify-between rounded-lg border border-border p-4 transition-colors hover:bg-secondary/50"
                  >
                    <div className="flex-1">
                      <Link href={`/signalements/${signalement.id}`} className="font-medium hover:text-primary">
                        {signalement.titre}
                      </Link>
                      <div className="mt-1 flex items-center gap-2">
                        <Badge
                          variant={
                            signalement.priorite === "HAUTE"
                              ? "destructive"
                              : signalement.priorite === "MOYENNE"
                                ? "default"
                                : "secondary"
                          }
                        >
                          {signalement.priorite}
                        </Badge>
                        <Badge variant="outline">{signalement.statut.replace("_", " ")}</Badge>
                      </div>
                    </div>
                    <span className="text-sm text-muted-foreground">{signalement.date}</span>
                  </div>
                ))}
              </div>
              <Button variant="outline" className="mt-4 w-full bg-transparent" asChild>
                <Link href="/signalements">Voir tous les signalements</Link>
              </Button>
            </CardContent>
          </Card>

          {/* Techniciens */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Users className="h-5 w-5" />
                Techniciens actifs
              </CardTitle>
              <CardDescription>Performance de l'équipe</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {techniciens.map((tech) => (
                  <div key={tech.nom} className="space-y-2">
                    <div className="flex items-center justify-between">
                      <span className="font-medium">{tech.nom}</span>
                    </div>
                    <div className="flex gap-4 text-sm text-muted-foreground">
                      <span>{tech.actifs} actifs</span>
                      <span className="text-accent">{tech.resolus} résolus</span>
                    </div>
                    <div className="h-2 w-full overflow-hidden rounded-full bg-secondary">
                      <div
                        className="h-full bg-accent"
                        style={{ width: `${(tech.resolus / (tech.resolus + tech.actifs)) * 100}%` }}
                      />
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Quick Actions */}
        <Card className="mt-8">
          <CardHeader>
            <CardTitle>Actions rapides</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid gap-4 md:grid-cols-3">
              <Button variant="outline" asChild>
                <Link href="/signalements/nouveau">Créer un signalement</Link>
              </Button>
              <Button variant="outline" asChild>
                <Link href="/admin/techniciens">Assigner un technicien</Link>
              </Button>
              <Button variant="outline" asChild>
                <Link href="/admin/rapports">Générer un rapport</Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      </main>
    </div>
  )
}
